//! The components a declaration file generated by `unplugin-vue-components` registers, and how Vue resolves a tag
//! name to one (ADR 0082).

use oxc_allocator::Allocator;
use oxc_ast::ast::{
    Argument, BindingPattern, CallExpression, Expression, Program, TSImportType, TSPropertySignature,
    VariableDeclarator,
};
use oxc_ast_visit::{Visit, walk};
use oxc_parser::Parser;
use oxc_span::SourceType;

/// A component registered globally by a generated declaration file:
/// `AppButton: typeof import('./src/components/AppButton.vue')['default']`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RegisteredComponent {
    /// The name the component is registered by; templates use it as written or in kebab-case.
    pub name: String,
    /// The module specifier as written, relative to the declaration file.
    pub specifier: String,
}

/// The components `source`, the text of a `components.d.ts` that `unplugin-vue-components` generated, registers from
/// files of the project, in source order: each property of `GlobalComponents` and each global `const` whose type is
/// `typeof import('./…')[…]`, as knip reads them. A `Lazy` variant of a registered name (`LazyAppIcon` beside
/// `AppIcon`) is the same component and is left out; a `LazyImage` registered on its own is a component of its own.
/// Components of packages (`typeof import('vant')['Button']`) are left out too: the declaration file keeps importing
/// them.
#[must_use]
pub fn registered_components(source: &str) -> Vec<RegisteredComponent> {
    let allocator = Allocator::default();
    let parsed = Parser::new(&allocator, source, SourceType::d_ts()).parse();
    let mut registrations = Registrations::default();
    registrations.visit_program(&parsed.program);
    let found = registrations.found;
    let is_variant = |component: &RegisteredComponent| {
        component.name.strip_prefix("Lazy").is_some_and(|base| {
            found
                .iter()
                .any(|other| other.name == base && other.specifier == component.specifier)
        })
    };
    found
        .iter()
        .filter(|component| !is_variant(component))
        .cloned()
        .collect()
}

/// Vue's `camelize`: each `-` before a word character is dropped and the character upper-cased (`my-button` as
/// `myButton`).
#[must_use]
pub fn camelize(name: &str) -> String {
    let mut camel = String::with_capacity(name.len());
    let mut chars = name.chars().peekable();
    while let Some(c) = chars.next() {
        match chars.peek() {
            Some(&next) if c == '-' && (next.is_ascii_alphanumeric() || next == '_') => {
                camel.push(next.to_ascii_uppercase());
                chars.next();
            }
            _ => camel.push(c),
        }
    }
    camel
}

/// Vue's `capitalize`: the first character upper-cased (`myButton` as `MyButton`).
#[must_use]
pub fn capitalize(name: &str) -> String {
    let mut chars = name.chars();
    chars
        .next()
        .map(|first| first.to_uppercase().chain(chars).collect())
        .unwrap_or_default()
}

/// The names Vue looks a tag up by, in its order and without repeats: as written, camelized, and camelized and
/// capitalised (`my-button`, `myButton`, `MyButton`). The compiler resolves a tag to a binding of the script this way,
/// and the runtime (`resolveAsset`) to a registered component.
#[must_use]
pub fn resolved_names(tag: &str) -> Vec<String> {
    let camel = camelize(tag);
    let pascal = capitalize(&camel);
    let mut names = vec![tag.to_owned()];
    for name in [camel, pascal] {
        if !names.contains(&name) {
            names.push(name);
        }
    }
    names
}

/// Whether `tag` is an element of HTML, SVG or MathML, or the `component` and `slot` of Vue's compiler, as written:
/// Vue never resolves such a tag to a registered component. The match is case-sensitive, as Vue's: `<Button>` is a
/// component.
#[must_use]
pub fn is_native_tag(tag: &str) -> bool {
    NATIVE_TAGS.contains(&tag)
}

/// The registered component the tag `tag` names, by [`resolved_names`], or by the name after a `Lazy` prefix
/// (`LazyAppButton`, `lazy-app-button`) as knip also matches it; `None` for a native tag ([`is_native_tag`]).
#[must_use]
pub fn registered_name(tag: &str, is_registered: impl Fn(&str) -> bool) -> Option<String> {
    if is_native_tag(tag) {
        return None;
    }
    let names = resolved_names(tag);
    names.iter().find(|name| is_registered(name)).cloned().or_else(|| {
        names
            .iter()
            .filter_map(|name| name.strip_prefix("Lazy"))
            .find(|base| is_registered(base))
            .map(str::to_owned)
    })
}

/// The names of the `resolveComponent('AppButton')` calls of `program` (also `_resolveComponent` and a member
/// `Vue.resolveComponent`) whose argument is a string: a render function resolves the registered component by it.
pub(crate) fn resolved_components(program: &Program<'_>) -> Vec<String> {
    let mut calls = ResolveCalls::default();
    calls.visit_program(program);
    calls.names
}

#[derive(Default)]
struct ResolveCalls {
    names: Vec<String>,
}

impl<'a> Visit<'a> for ResolveCalls {
    fn visit_call_expression(&mut self, it: &CallExpression<'a>) {
        let callee = match &it.callee {
            Expression::Identifier(id) => Some(id.name.as_str()),
            Expression::StaticMemberExpression(member) => Some(member.property.name.as_str()),
            _ => None,
        };
        if callee.is_some_and(|callee| matches!(callee, "resolveComponent" | "_resolveComponent")) {
            let name = match it.arguments.first() {
                Some(Argument::StringLiteral(literal)) => Some(crate::js_string(literal.value)),
                Some(Argument::TemplateLiteral(literal)) if literal.expressions.is_empty() => literal
                    .quasis
                    .first()
                    .and_then(|quasi| quasi.value.cooked)
                    .map(crate::js_string),
                _ => None,
            };
            if let Some(name) = name.filter(|name| !name.is_empty()) {
                self.names.push(name);
            }
        }
        walk::walk_call_expression(self, it);
    }
}

