#[derive(Default)]
struct Registrations {
    /// The name of the property or constant whose type is being read.
    current: Option<String>,
    found: Vec<RegisteredComponent>,
}

impl Registrations {
    fn within(&mut self, name: Option<String>, body: impl FnOnce(&mut Self)) {
        self.current = name;
        body(self);
        self.current = None;
    }
}

/// A relative specifier that does not go through `node_modules`.
fn is_local(specifier: &str) -> bool {
    specifier.starts_with('.') && !specifier.split('/').any(|segment| segment == "node_modules")
}

impl<'a> Visit<'a> for Registrations {
    fn visit_ts_property_signature(&mut self, it: &TSPropertySignature<'a>) {
        let name = it.key.static_name().map(|key| crate::js_string(key.as_js_str()));
        self.within(name, |this| walk::walk_ts_property_signature(this, it));
    }

    fn visit_variable_declarator(&mut self, it: &VariableDeclarator<'a>) {
        let name = match &it.id {
            BindingPattern::BindingIdentifier(id) => Some(id.name.as_str().to_owned()),
            _ => None,
        };
        self.within(name, |this| walk::walk_variable_declarator(this, it));
    }

    fn visit_ts_import_type(&mut self, it: &TSImportType<'a>) {
        // The first `import()` type of a registration names its module.
        if let Some(name) = self.current.take() {
            let specifier = crate::js_string(it.source.value);
            if is_local(&specifier) {
                self.found.push(RegisteredComponent { name, specifier });
            }
        }
        walk::walk_ts_import_type(self, it);
    }
}

#[cfg(test)]
mod tests {
    use oxc_allocator::Allocator;
    use oxc_parser::Parser;
    use oxc_span::SourceType;

    use super::{
        RegisteredComponent, camelize, is_native_tag, registered_components, registered_name, resolved_components,
        resolved_names,
    };

    fn component(name: &str, specifier: &str) -> RegisteredComponent {
        RegisteredComponent {
            name: name.to_owned(),
            specifier: specifier.to_owned(),
        }
    }

    #[test]
    fn reads_the_local_components_of_the_interface_and_the_globals() {
        let source = "/* eslint-disable */\n// Generated by unplugin-vue-components\nexport {}\ndeclare module 'vue' {\n  export interface GlobalComponents {\n    AppButton: typeof import('./src/components/AppButton.vue')['default']\n    'AppCard': typeof import('./src/components/AppCard.vue')['default']\n    VanButton: typeof import('vant/es')['Button']\n    Hidden: typeof import('./node_modules/x/Hidden.vue')['default']\n  }\n}\ndeclare global {\n  const AppIcon: typeof import('./src/components/AppIcon.vue')['default']\n  const LazyAppIcon: typeof import('./src/components/AppIcon.vue')['default']\n}\n";
        let found = registered_components(source);
        let expected = [
            ("AppButton", "./src/components/AppButton.vue"),
            ("AppCard", "./src/components/AppCard.vue"),
            ("AppIcon", "./src/components/AppIcon.vue"),
        ]
        .map(|(name, specifier)| RegisteredComponent {
            name: name.to_owned(),
            specifier: specifier.to_owned(),
        });
        assert_eq!(found, expected);
    }

    #[test]
    fn a_lazy_name_is_left_out_only_as_the_variant_of_a_registered_one() {
        let source = "// Generated by unplugin-vue-components\ndeclare global {\n  const AppIcon: typeof import('./src/AppIcon.vue')['default']\n  const LazyAppIcon: typeof import('./src/AppIcon.vue')['default']\n  const LazyImage: typeof import('./src/LazyImage.vue')['default']\n}\n";
        assert_eq!(
            registered_components(source),
            [
                component("AppIcon", "./src/AppIcon.vue"),
                component("LazyImage", "./src/LazyImage.vue"),
            ]
        );
    }

    #[test]
    fn tags_resolve_as_vue_resolves_them() {
        assert_eq!(camelize("u-i-button"), "uIButton");
        assert_eq!(camelize("my-button-2"), "myButton2");
        assert_eq!(resolved_names("my-button"), ["my-button", "myButton", "MyButton"]);
        assert_eq!(resolved_names("myButton"), ["myButton", "MyButton"]);
        assert_eq!(resolved_names("AppButton"), ["AppButton"]);
        let registered = ["MyButton", "UIButton", "AppIcon", "Button"];
        let lookup = |tag: &str| registered_name(tag, |name| registered.contains(&name));
        for (tag, name) in [
            ("myButton", "MyButton"),
            ("my-button", "MyButton"),
            ("MyButton", "MyButton"),
            ("u-i-button", "UIButton"),
            ("UIButton", "UIButton"),
            ("lazy-app-icon", "AppIcon"),
            ("LazyAppIcon", "AppIcon"),
            ("Button", "Button"),
        ] {
            assert_eq!(lookup(tag).as_deref(), Some(name), "{tag}");
        }
        // `ui-button` is `UiButton` to Vue, and native tags are never components.
        for tag in ["ui-button", "button", "template", "script", "style", "div", "svg"] {
            assert_eq!(lookup(tag), None, "{tag}");
        }
        assert!(is_native_tag("clipPath"));
        assert!(!is_native_tag("Div"));
    }

    #[test]
    fn resolve_component_calls_name_components() {
        let source = "import { resolveComponent, h } from 'vue';\nexport default { render() { return [h(resolveComponent('AppButton')), Vue.resolveComponent(`app-card`), _resolveComponent(\"AppIcon\"), resolveComponent(name)]; } };\n";
        let allocator = Allocator::default();
        let parsed = Parser::new(&allocator, source, SourceType::mjs()).parse();
        assert_eq!(
            resolved_components(&parsed.program),
            ["AppButton", "app-card", "AppIcon"]
        );
    }
}
